/* Marico-only business lesson. Product revenue and geographical profits have different scopes. */
(()=>{
 const id='marico',c=window.COMPANIES.find(c=>c.id===id),previous=window.companyPrimer;
 const urls={brands:'https://marico.com/india/brands',company:'https://marico.com/india/about-us',annual:'https://marico.com/investorspdf/Marico_Annual_Report_FY26.pdf',reports:'https://marico.com/india/investors/annual-report',shampoo:'https://marico.com/global/media/detail/what_makes_heads_turn_the_newly_launched_parachute_advansed_protein_shampoo_reveals_the_answer_in_its_first_campaign_film_aisa_kya_hai?id=260&type=press'};
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const note=(url,label,location='')=>`<p class="source-note"><a href="${url}" target="_blank" rel="noopener">${label} ↗</a>${location?` · ${location}`:''}</p>`;
 c.summary='The business behind Parachute coconut oil, Saffola oils and foods, Livon hair care and Beardo grooming, with consumer brands in India and overseas.';
 c.description="Marico sells coconut oil, cooking oils, packaged foods and grooming or personal-care products. It buys ingredients and packaging, arranges production, advertises the brands and supplies shops and online sellers. A Parachute bottle, a Saffola oil pack and a grooming product meet different needs and cost different amounts to make and sell.";
 c.money="Marico records sales by supplying consumer goods to shops, retail chains and online sellers in India and overseas. Ingredients, packaging, production, transport and advertising must be paid before profit remains. Higher sales can come from higher prices or different products, without customers buying a larger quantity.";
 c.productSource=urls.brands;
 c.products=c.products.map(([name,type])=>[name,name==='Plix'?'Nutrition and personal care':name==='True Elements'?'Breakfast foods and snacks':type]);
 if(!c.products.some(([name])=>name==='Kaya personal care'))c.products.push(['Kaya personal care','Sales and marketing rights outside Kaya clinics · not clinic ownership']);
 c.productNote='Selected offering families from the official India directory, international portfolio and FY 2025–26 business review. Variants and pack sizes are grouped. Parachute and Parachute Advansed are separate brands. Marketing rights, subsidiaries and acquired brands are different relationships; this list is not an assertion of full ownership of every brand or business.';
 window.COMPANY_OVERVIEWS[id]={"customers": "Households buy through local shops, retail chains, brand websites and other online stores. A distributor buys stock and supplies shops, so the customer paying Marico may differ from the person using the product.", "drivers": "Quantities sold, pack sizes, prices and the kinds of products bought. Copra means dried flesh from inside a coconut used to make coconut oil; its cost, other ingredients, packaging, advertising and delivery all affect earnings."};
 c.watch=[
  ['Is growth coming from quantities, prices or pack sizes?','Read volume and sales together, especially where a pack keeps its price but contains a different quantity.'],
  ['How are copra and edible-oil costs reaching earnings?','Check buying costs, stock bought earlier, selling-price changes and what consumers do in response.'],
  ['Are shops and online channels building repeat demand?','Separate wider distribution and channel stock from shoppers buying and using the products.'],
  ['Are foods and digital brands earning sustainable sales?','Read repeat purchases, marketing costs, actual sales and profitability alongside new launches and revenue run-rates.'],
  ['What is happening within the international business?','Look at individual markets, constant-currency growth, exchange rates, input costs and local conditions.'],
  ['Do acquisitions and investment turn earnings into useful cash?','Check the entity acquired, period included, ownership interest, working capital and the cash spent on growth.']
 ];
 window.COMPANY_RESEARCH_GUIDES[id]=[
  'Read the company’s stated volume basis alongside revenue and product-mix commentary. The FY 2025–26 Parachute review distinguishes reported volumes from transaction-level growth adjusted for reduced pack contents. Compare equivalent quantities where possible; neither a count of packs nor sales growth alone establishes how much more product consumers used.',
  'Copra is dried flesh from inside a coconut used to make coconut oil. Follow its cost separately from the vegetable-oil inputs used in edible-oil offerings. The cost of stock already bought and the timing of pricing changes can delay the impact on earnings. Read category commentary, gross margin and consumer demand together; lower raw-material prices need not become higher profit if selling prices fall too.',
  'Read distribution commentary, inventory and customer amounts still due alongside sales. General trade means local shops; modern trade means organised retail. Digital-first brands can sell through their own websites, marketplaces and offline outlets. Reaching more shops or shipping more stock into a channel does not by itself prove repeat purchases or better cash generation.',
  'Distinguish actual revenue for a completed period from an annualised revenue run-rate, which extends a recent sales pace across a year. Read which brands and channels are included and whether a margin is achieved or targeted. Advertising, platform fees, delivery, returns and repeat customers affect online economics. Portfolio-level or brand-level EBITDA claims are not the same measure as the geographical PBIT table here.',
  'Read Bangladesh, Vietnam, Middle East and North Africa (MENA), and South Africa commentary rather than treating International as one uniform market. Constant-currency growth removes exchange-rate effects on the stated basis; rupee growth includes currency translation. Country mix, inflation, logistics and regulations can affect results. A subsidiary’s local-currency accounts and the consolidated International segment are different reporting scopes.',
  'Use the acquisition, subsidiary and cash-flow notes to identify closing dates, control, remaining interests and the period consolidated. Separate growth in existing businesses from revenue added through acquisitions. Then read inventory, receivables, supplier balances, capital spending and acquisition payments. The amount paid for a brand and the revenue it reports do not establish the return earned on the purchase.'
 ];
 c.risks=[
  ['Raw materials rise faster than shoppers accept price changes','Copra, vegetable oils and packaging can become more expensive. Pricing or pack-size changes may offset costs but can also weaken demand. Cost movements affect categories differently.'],
  ['Growth relies too heavily on familiar franchises','Established oil brands support the business, while other branded and unbranded alternatives compete for household spending. A weakness in an important franchise can outweigh growth in smaller categories.'],
  ['Newer brands need more spending than repeat demand supports','Foods, grooming and other newer offerings require marketing, distribution and product development. Large online sales or a launch announcement do not establish attractive profit or a return on acquisition spending.'],
  ['Overseas conditions change the rupee result','Exchange rates, local inflation, regulation, political disruption and logistics can affect individual markets. A healthy demand trend in one country may not offset pressure elsewhere.'],
  ['Quality, labels or claims damage trust','Consumer products depend on consistent quality and compliant labelling and marketing. A brand’s wellness positioning is not evidence of a health benefit. Assess the actual scope of any official finding and corrective action.']
 ];
 c.update=['A familiar hair-care brand can face a new kind of competition','Marico’s July 2026 campaign describes Parachute Advansed Protein Shampoo. Moving from oil-based hair care into shampoo changes the product format, competing alternatives and purchase habits. Brand recognition can help a launch, but distribution, repeat demand and the costs of competing still need to be demonstrated. This is a dated product reference, not a claim that the new offering has achieved a particular profit.'];
 c.question='If Marico’s sales rise while oil prices rise, has consumer demand necessarily grown by the same amount?';
 c.answer='No. Higher selling prices, a different product mix, smaller packs and acquisitions can change revenue without the same increase in quantity consumed. Read the volume definition and pricing commentary, then compare the matching profit and cash-flow measures. Sales growth and demand growth answer different questions.';
 for(const p of [['FY 2025–26 integrated annual report · business reviews and accounts',urls.annual],['Marico annual-report library',urls.reports],['Parachute Advansed shampoo · July 2026 campaign',urls.shampoo]])if(!c.sources.some(([,url])=>url===p[1]))c.sources.push(p);
 const groups=[
  ['Coconut oil and hair oils','Parachute coconut oil; Parachute Advansed, Hair & Care and Nihar hair-oil offerings.','Parachute and Parachute Advansed are separate brands. A pure coconut-oil offering and a formulated hair-care product can have different ingredients, positioning and alternatives.','Copra costs, pack quantities, pricing and repeat purchases. Copra is dried flesh from inside a coconut, a raw material for coconut oil.'],
  ['Cooking oils and packaged foods','Saffola edible oils and foods such as oats, soya chunks, honey and muesli; True Elements breakfast foods; Cosmix nutrition offerings and 4700BC snacks.','A shared brand does not make cooking oil and a breakfast food the same economic activity. Recipes, raw materials, usage occasions and competition differ.','Follow affordability, taste, distribution and whether newer products become repeat purchases. Nutrition or wellness positioning does not prove a health benefit or a profitable business.'],
  ['Grooming and personal care','Livon hair care, Set Wet grooming, Beardo, Just Herbs and Plix personal-care offerings illustrate this part of the portfolio.','Digital-first describes how a brand was built and reaches buyers; it does not mean the brand only sells on its own website. Plix appears across nutrition and personal care.','Advertising, marketplace terms, delivery and returns, alongside repeat demand. A higher price does not automatically mean a higher profit.'],
  ['Consumer products outside India','Examples in the international portfolio include Parachute, X-Men, HairCode, Purité de Prôvence and Candid, depending on the market.','The group operates through different markets and entities. The international range is not simply the India catalogue sold everywhere.','Read local demand, distribution, currency and operating conditions before interpreting the combined International result.']
 ];
 const basics=`<section class="content-section company-primer" id="marico-basics"><div class="number">START WITH THE PRODUCTS</div><h2>Similar shelves. Different buying habits and costs.</h2><p>Start with a Parachute bottle, a Saffola cooking-oil pack, a bowl of Saffola oats and a Beardo grooming product. They share a group behind them, but people buy them for different reasons. Marico’s business is to make the offering available, trusted and worth buying again.</p><div class="primer-groups">${groups.map(([name,examples,meaning,drivers])=>`<div><h3>${name}</h3><p><strong>What it sells:</strong> ${examples}</p><p>${meaning}</p><p><strong>What to understand:</strong> ${drivers}</p></div>`).join('')}</div>${note(urls.brands,'Official India product and brand directory')}${note(urls.annual,'Annual report: India and international business reviews','Product showcase and Management Discussion and Analysis')}
 <h3>A brand, a product family and a reporting segment are different</h3><p>Saffola is a brand spanning different offerings; edible oils and foods help describe product families. Marico’s reported operating segments are <strong>India</strong> and <strong>International</strong>. They group many products and brands, so their profits cannot be assigned to a single bottle or brand.</p><p>The annual report also supplies revenue by major product category. Its reporting labels need to be read as published rather than reconstructed from where a shopper might use a product. The actual tables appear at the end.</p>${note(urls.annual,'Consolidated Note 30: segment and product-category reporting','Printed pages 434–435')}
 <h3>Who pays Marico?</h3><p>A distributor, retailer or online channel may buy stock before a household buys and uses the finished product. In a direct website sale, the route is shorter, but fulfilment and customer acquisition still cost money. Selling into a channel is different from a consumer coming back for another purchase.</p></section>`;
 const specifics=`<section class="content-section company-primer" id="marico-specifics"><div class="number">HOW THIS BUSINESS WORKS</div><h2>Follow the ingredient, the pack and the next purchase.</h2><ol class="primer-route"><li><strong>Buy ingredients and packaging</strong><span>Buy ingredients such as copra, which is dried flesh from inside a coconut, as well as oils and packaging. Availability and purchase prices affect costs.</span></li><li><strong>Develop, manufacture and check</strong><span>Turn inputs into consistent products, arrange relevant production and quality controls, and prepare the pack for its intended use and storage.</span></li><li><strong>Get products to shops and online sellers</strong><span>Supply local shops, organised retail, marketplaces, fast-delivery channels or brand websites under the relevant arrangement.</span></li><li><strong>Earn a repeat purchase</strong><span>Price, quantity, quality, availability and competing choices determine whether a shopper buys again.</span></li></ol><p>This is a simplified route. Product families and countries use different supply, manufacturing and commercial arrangements.</p>${note(urls.annual,'Annual report: sourcing, operations and distribution')}
 <h3>Why oil prices can make growth difficult to read</h3><p>When raw materials become more expensive, the company may change prices or pack contents. Sales can rise even if the quantity sold changes little. If prices rise too far, shoppers may choose a smaller pack, another brand or an unbranded alternative.</p><p>The reverse needs checking too: lower input costs may be passed on through cheaper prices or larger packs. Stock bought at earlier prices and the timing of price changes can delay the effect on earnings.</p><div class="primer-examples"><div><h4>Compare quantities on the same basis</h4><p>A pack can keep its familiar price while containing fewer millilitres. A count of transactions and the amount of oil sold can therefore move differently.</p><span>Marico’s FY 2025–26 Parachute review discusses this distinction. Check what its volume measure actually includes.</span></div><div><h4>Do not confuse run-rate with annual sales</h4><p>An annualised revenue run-rate extends a recent sales pace across a year. It is not automatically the revenue already earned over a completed financial year.</p><span>Read the period, included brands and any acquisition dates before comparing it with the company’s annual results.</span></div><div><h4>Separate reach from repeat demand</h4><p>More outlets or online visibility can improve availability. Advertising, channel fees, delivery and stock still have to be paid for.</p><span>Look for evidence of sustained demand, the relevant profit definition and cash generation rather than treating reach as a return on spending.</span></div></div>${note(urls.annual,'Annual review: Parachute, digital-first portfolio and distribution','Printed pages 230–233')}
 <h3>Understand what the company owns and what it markets</h3><p>Marico’s portfolio includes established brands, businesses acquired through subsidiaries and specific commercial rights. Its brand directory states that it has exclusive sales and marketing rights for Kaya personal-care products outside Kaya clinics. That does not mean Marico owns Kaya’s clinic business.</p><p>For an acquisition, read the entity, the interest acquired, whether control was obtained and when its results enter the group accounts. A newly acquired business can add sales even when the earlier business has not sold more. This is different from growth within the existing portfolio.</p>${note(urls.brands,'Official Kaya sales-and-marketing rights footnote')}${note(urls.annual,'Annual report: acquisition and subsidiary notes')}
 <h3>Read international growth in its local setting</h3><p>Marico’s international operations span markets with different customers, currencies and conditions. <strong>Constant-currency growth</strong> removes exchange-rate effects on the company’s stated basis. Growth reported in rupees also reflects conversion from local currencies.</p><p>Country mix and input costs still matter after that adjustment. A currency-adjusted growth figure is not a profit measure, and performance in one country does not establish that every overseas operation is doing equally well.</p>
 <details class="primer-detail"><summary>Useful words in Marico’s reports</summary><dl class="primer-glossary">${[
 ['Copra','Dried coconut kernel used to make coconut oil. Its supply and price are a different issue from the prices of other vegetable oils.'],
 ['Volume, price and mix','Quantity sold on the stated basis, the realised selling price and the balance of products sold. Pack-size changes can make transaction counts and physical quantities differ.'],
 ['Digital-first and D2C','Digital-first describes a brand built around digital discovery and sales. Direct-to-consumer means selling directly to the shopper; a digital-first brand may also use marketplaces, shops and other channels.'],
 ['A&P','Advertising and sales-promotion spending. It is a cost of building demand, not evidence by itself that the spending has earned a return.'],
 ['ARR in this business review','Annualised revenue run-rate: a recent revenue pace extended across a year. Do not assume it means annual recurring revenue or actual revenue for a completed financial year.'],
 ['PBIT and EBITDA','Profit before interest and tax and earnings before interest, tax, depreciation and amortisation are different measures. The reported geographical segment result also needs company-level reconciliation.'],
 ['Working capital','Stock, money customers owe and supplier-payment arrangements affect the cash required to run the business. Accounting profit can grow while more cash is tied up.']
 ].map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl></details><p class="source-note">Business explanations checked 29 October 2026 against the linked Indian brand directory, FY 2025–26 annual report and dated product announcement. Investigation prompts are questions to assess, not findings that a brand, acquisition or channel earns an attractive return.</p></section>`;
 function numbers(){const f=window.COMPANY_FINANCIALS[id],p=f.productRevenue,fmt=n=>new Intl.NumberFormat('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n),india=f.rows.find(r=>r.name==='India'),international=f.rows.find(r=>r.name==='International');return `<div class="primer-number-guide"><h3>Which product categories generate revenue?</h3><p>This FY 2025–26 consolidated disclosure shows <strong>product-category revenue only</strong>. The labels below are those in the annual report; they are not a separate profit statement for Saffola, Parachute or any other brand.</p><table class="financial-table"><caption class="sr-only">Marico consolidated product-category revenue, FY 2025–26. No category profit allocation.</caption><thead><tr><th scope="col">Reported product category</th><th scope="col">Revenue<br><small>₹ crore</small></th><th scope="col">Share of total<br><small>% · calculated</small></th></tr></thead><tbody>${p.rows.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${fmt(r.revenue)}</td><td>${(r.revenue/p.total*100).toFixed(2)}%</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Reported total</th><td>${fmt(p.total)}</td><td>100%</td></tr></tfoot></table><p>The category rows and the India/International rows are <strong>two views of the same group revenue</strong>. Do not add the two tables together. The annual report does not provide a matching separate profit for each of these product categories in this note.</p><p>Shares are calculated as category revenue ÷ reported total × 100. Rounded percentages may not add to exactly 100%. A revenue share is not a profit share.</p>${note(p.source,'Official product-category revenue disclosure',esc(p.location))}
 <h3>More sales and a higher result per sale are different</h3><p>India has both more revenue and more reported segment profit than International in the main table. For each ₹100 of segment revenue, the segment result is approximately <strong>₹${(india.profit/india.revenue*100).toFixed(2)} for India</strong> and <strong>₹${(international.profit/international.revenue*100).toFixed(2)} for International</strong>.</p><p>Calculated as reported segment result ÷ the corresponding segment revenue × 100. These are calculated segment-result-to-sales ratios, not a brand margin, the company’s separately defined EBITDA margin, profit after tax or a shareholder return. Different products and markets help explain why the ratios can differ.</p>
 <details class="primer-detail"><summary>How does segment result become company profit?</summary><p>The combined ₹${fmt(f.profitTotal)} crore segment result is reduced by ₹${fmt(p.financeCosts)} crore of finance costs and ₹${fmt(p.unallocatedNetExpense)} crore of net unallocated expenditure to reach ₹${fmt(p.pbt)} crore profit before tax.</p><p>Tax of ₹${fmt(p.tax)} crore leaves ₹${fmt(p.groupPat)} crore group profit after tax. After ₹${fmt(p.nonControlling)} crore belonging to non-controlling interests, profit attributable to owners is ₹${fmt(p.ownersPat)} crore. These are successive, differently defined measures. The segment-result total should not be called net profit.</p>${note(p.source,'Official reconciliation and consolidated results','Note 30 · printed pages 434–435; management review · printed page 234')}</details><p>For the next checks, read operating cash flow, inventory, customer and supplier balances, factory spending and acquisition payments. Neither these earnings figures nor a brand’s popularity establish whether the current share price offers good value.</p></div>`}
 if(window.PRODUCT_VISUALS){const old=window.PRODUCT_VISUALS[id].map(p=>({...p,url:urls.brands,category:p.name==='Plix'?'Nutrition and personal care':p.category,alt:`${p.name} — official ${p.kind==='brand'?'brand':'product'} image`})),first=['Parachute','Saffola','Saffola Foods','Beardo'].map(name=>old.find(p=>p.name===name)).filter(Boolean);window.PRODUCT_VISUALS[id]=[...first,...old.filter(p=>!first.includes(p))];}
 window.companyPrimer={skipBusiness(company){return company.id===id||!!previous?.skipBusiness(company);},render(company,slot){if(company.id!==id)return previous?.render(company,slot)||'';return slot==='basics'?basics:slot==='specifics'?specifics:slot==='numbers'?numbers():'';},contents(company){return company.id===id?[['marico-basics','Marico from the basics'],['marico-specifics','How Marico works']]:previous?.contents(company)||[]}};
})();
